import{z as n,x as A,o as B,c as m,q as i,j as l,D as r,d as E,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"稀有灾难","description":"","frontmatter":{"title":"稀有灾难","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rare-disasters.md","filePath":"econ/rare-disasters.md","lastUpdated":1791413859000}'),p={name:"econ/rare-disasters.md"};function d(D,a,u,c,h,f){const t=A("Mermaid");return B(),m("div",null,[a[2]||(a[2]=i('<h1 id="稀有灾难" tabindex="-1">稀有灾难 <a class="header-anchor" href="#稀有灾难" aria-label="Permalink to &quot;稀有灾难&quot;">​</a></h1><div class="epigraph"><p>样本里看不见的崩溃，仍可以进入定价核：很小的概率乘上消费的巨幅下降，足以抬高股权溢价，而不必把平常年份的 $\\gamma$ 拧到两位数。</p><footer>—— Rietz, The Equity Risk Premium: A Solution, Journal of Monetary Economics, 1988；Barro, Rare Disasters and Asset Markets in the Twentieth Century, Quarterly Journal of Economics, 2006</footer></div><p><a href="/econ/long-run-risk">上一课</a>用持久增长新闻造续值波动。并列的第三条路是尾部：平常年份的 \\(\\Delta c\\) 仍平滑，但存在低概率的灾难状态。本课缺口是 Rietz 的提议与 Barro 的历史校准。不重做 Bansal–Yaron 的 \\(x_t\\)，不把灾难写成期权隐含面的交易策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mehra–Prescott 的马尔可夫消费取自和平时期的美国增长，几乎没有战争、瘟疫、政治崩溃那一档的下降。Rietz（1988）指出：若加入一个小概率、大降幅的状态，CRRA 核在该状态极高，\\(m\\) 的均值与协方差可以同时抬溢价、并帮助 \\(r_f\\)。批评是：所要的崩溃是否大到离谱。Barro（2006）用二十世纪多国的真实灾难（战争、革命）重新定量：降幅与频率不必像讽刺漫画那么极端，也可以进入资产定价的量级。</p><p>缺口是把「样本低估了 \\(\\sigma(m)\\) 的尾」写成一种修补，而不是宣布股市永远便宜。习惯与长期风险改的是平常年份的 \\(m\\)；灾难改的是支撑的测度。</p><p><span class="marginnote">数字实例：\\(\\gamma=5\\) 时，消费掉三成（\\(\\Delta=0.3\\)）的灾难状态里，核是 \\((0.7)^{-5}\\approx6\\)。一个发生概率不到 2% 的状态，定价权重就顶得上平时几十年的小波动加总——尾巴虽细，杆秤极沉。</span></p><p><span class="marginnote">灾难是消费（或产出、股利）的大幅、持久或至少数年的下降，不是一日的股市回撤。用股价自己定义灾难，会把要解释的对象放进解释项。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在消费过程上加一个跳跃或一个低频马尔可夫状态：以 \\(p\\) 掉到 \\(1-\\Delta\\) 的消费水平。CRRA 下该状态的 \\(m\\) 为 \\(\\beta(1-\\Delta)^{-\\gamma}\\)，即使 \\(p\\) 很小，\\(\\mathrm{E}[m R^e]\\) 也可以被这一项主导——股票在灾难里恰好大亏，国债相对好。Weil 的 \\(r_f\\) 也会被 \\(\\mathrm{E}[m]\\) 拉低；是否同时舒服，仍取决于 \\(p\\)、\\(\\Delta\\)、\\(\\gamma\\) 与是否允许违约。</p>',10)),(B(),l(o,null,{default:r(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEACE%5B%22%E5%B9%B3%E5%B8%B8%E5%B9%B4%E4%BB%BD%3A%20Delta%20c%20%E5%B9%B3%E6%BB%91%22%5D%20--%3E%20MP%5B%22%E5%B8%B8%E8%A7%84%20CRRA%20%E6%A0%B8%E5%A4%AA%E5%B9%B3%22%5D%0A%20%20DIS%5B%22%E5%B0%8F%E6%A6%82%E7%8E%87%E5%A4%A7%E9%99%8D%E5%B9%85%22%5D%20--%3E%20TAIL%5B%22m%20%E5%9C%A8%E7%81%BE%E9%9A%BE%E7%8A%B6%E6%80%81%E6%9E%81%E5%A4%A7%22%5D%0A%20%20TAIL%20--%3E%20EP%5B%22%E8%82%A1%E6%9D%83%E6%BA%A2%E4%BB%B7%E4%B8%8A%E5%8D%87%22%5D%0A%20%20TAIL%20--%3E%20RF%5B%22E%5Bm%5D%20%E5%8D%87%2C%20rf%20%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("本课不审 Barro 表格里的百分点。只要钉：两谜可以是"),e("strong",null,"未观察到的状态"),E("问题，而不只是偏好函数形式问题。EZ 与灾难可叠加（对尾部的态度由 \\(\\gamma\\) 管）；习惯可让灾难附近的 surplus 更糟。并列，不互吞。")],-1)),a[4]||(a[4]=e("h3",{id:"样本选择不是抬杠",tabindex:"-1"},[E("样本选择不是抬杠 "),e("a",{class:"header-anchor",href:"#样本选择不是抬杠","aria-label":'Permalink to "样本选择不是抬杠"'},"​")],-1)),a[5]||(a[5]=e("p",null,"战后美国消费路径条件于「没有发生那些灾难」。用这条路径估 \\(\\sigma(\\Delta c)\\)，再要求 \\(\\gamma\\sigma(\\Delta c)\\) 匹配无条件溢价，是用条件矩去配无条件风险价格。Rietz–Barro 的逻辑是把无条件支撑补上。生存偏差、事前溢价是否等于事后均值，会改变量级，不取消这道逻辑。",-1)),a[6]||(a[6]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=e("p",null,"机制是跨状态的保险价格。股权是对总消费的要求权，灾难里赔钱，必须在平常年份提供溢价，作为持有该风险的补偿。国债若在灾难里相对兑现，其溢价低、价格高、收益率低。若主权债也会在同一灾难里违约，国债就不再是好的对冲，利率之谜的解变窄——Barro 后文讨论过这一点，本课标明边界即可。",-1)),(B(),l(o,null,{default:r(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20STOCK%5B%22%E8%82%A1%E7%A5%A8%3A%20%E5%AF%B9%E6%80%BB%E6%B6%88%E8%B4%B9%E7%9A%84%E8%A6%81%E6%B1%82%E6%9D%83%22%5D%20--%3E%20LOSS%5B%22%E7%81%BE%E9%9A%BE%E9%87%8C%E9%9A%8F%E6%B6%88%E8%B4%B9%E4%B8%80%E8%B5%B7%E5%A4%A7%E4%BA%8F%22%5D%0A%20%20LOSS%20--%3E%20BAD%5B%22%E5%9D%8F%E5%AF%B9%E5%86%B2%2C%20%E6%8C%81%E6%9C%89%E8%BF%99%E4%BB%BD%E9%A3%8E%E9%99%A9%E5%BE%88%E8%B4%B5%22%5D%0A%20%20BAD%20--%3E%20PREM%5B%22%E5%B9%B3%E5%B8%B8%E5%B9%B4%E4%BB%BD%E8%A6%81%E4%BB%98%E8%82%A1%E6%9D%83%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20BOND%5B%22%E5%9B%BD%E5%80%BA%3A%20%E7%81%BE%E9%9A%BE%E9%87%8C%E7%9B%B8%E5%AF%B9%E7%85%A7%E4%BB%98%22%5D%20--%3E%20GOOD%5B%22%E5%A5%BD%E5%AF%B9%E5%86%B2%2C%20%E5%A4%A7%E5%AE%B6%E6%8A%A2%E7%9D%80%E8%A6%81%22%5D%0A%20%20GOOD%20--%3E%20LOW%5B%22%E4%BB%B7%E6%A0%BC%E6%8A%AC%E9%AB%98%2C%20%E6%94%B6%E7%9B%8A%E7%8E%87%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p>HJ 仍成立：无条件 \\(\\sigma(m)\\) 可以很大，即使条件于和平样本的 \\(\\sigma(\\Delta c)\\) 很小。有效市场分层不因此改写：灾难风险被定价，不是「市场无效所以买股票」。</p><p><span class="marginnote">Rietz, <em>JME</em> 1988；Barro, <em>QJE</em> 2006。不要发明 arXiv。灾难概率可以从期权或跨国频率来谈，那是测量，本课不把隐含面写成定理。</span></p><p><span class="marginnote">直觉类比：把股权想成「和平时发糖、灾难时第一个被征走」的资产。要人自愿常年持有，平时就得一直发甜头——溢价不是奖励眼光好，是给灾难站岗的工资。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成「所以应该永远满仓股票」——溢价是对灾难的补偿，实现路径可以很久没有灾难。也不要把尾部因子、低波异象在此排序。下一课回到 <a href="/econ/ccapm">消费 CAPM</a> 的 beta 语言：修补链到此收束，Breeden 仍用消费当充分统计，实证薄弱换栏。</p><p><span class="marginnote">常见误区：初学者容易把「灾难溢价」读成「预期收益高，所以该加杠杆」。这份补偿对应的是几十年可能都不出现的尾部；事后看，溢价可以长期为零甚至为负——站岗的工资不等于天天有灾。</span></p><p>后课默认：稀有灾难可以在不抬平常 \\(\\gamma\\) 的情况下抬 \\(\\sigma(m)\\)。习惯改参照，长期风险改谱，灾难改支撑；三者都是对时间可分和平样本 CRRA 的修补。</p><p>期权隐含灾难、跨境灾难保险的交易协议不进限价簿课。本栏停在 \\(m\\) 的形状。</p><p>主权债若在同一灾难里违约，国债不再是好的对冲，\\(r_f\\) 之谜不能靠 \\(\\mathrm{E}[m]\\) 单独关掉。股权与国债在尾部的相对表现，是这条修补的识别，不是「股票永远涨」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rietz：小概率消费崩溃可解股权溢价；Barro 用跨国历史把量级写回可讨论区。</li><li>和平样本的 \\(\\sigma(\\Delta c)\\) 低估无条件 \\(\\sigma(m)\\) 的尾。</li><li>与习惯、长期风险并列，不互相替代，也不否证存在 \\(m\\)。</li><li>股权在灾难里赔钱才要求平常年份的溢价；「永远满仓」不是推论。</li><li>下一课消费 CAPM 把同一核写成 beta，截面弱斜率换栏。</li><li>用股价自己定义灾难，会把要解释的对象放进解释项。</li><li>国债若在同一灾难里违约，利率之谜的解变窄。</li><li>期权隐含面是测量，本课不把隐含灾难写成定理。</li><li>出处：Rietz, <em>JME</em> 1988。</li></ul>',11))])}const _=n(p,[["render",d]]);export{C as __pageData,_ as default};
